export function drawReceiptGear(doc, x, y, size) {
  const scale = size / 734;
  doc.setFillColor(0);
  doc.path(gearPath.map(([op, ...coordinates]) => ({
    op,
    c: coordinates.map((value, index) => value * scale + (index % 2 === 0 ? x : y))
  })));
  doc.fill();
}
